with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('tage ved lære', 'phrase', '0ed08560-cf1c-5ad5-86eb-10443a0e98f1', 1, 'verb', null, 'to learn from experience', 'Han tog ved lære af sine fejl.', 'He learned from his mistakes.'), ('rejse sig op', 'phrase', '42d159f1-2083-5317-97e4-3a972236f90c', 1, 'verb', null, 'to stand up (from sitting or lying)', 'Hun rejser sig op fra stolen og går hen til vinduet.', 'She gets up from her chair and walks to the window.'), ('være ude at rejse', 'phrase', 'ae654ce7-46ad-5363-841d-e575c203e667', 1, 'verb', null, 'to be travelling (away on a trip)', 'Min søster er ude at rejse i denne uge.', 'My sister is traveling this week.'), ('lukke ned', 'phrase', '0333cfd9-032e-5060-a7ef-744996e6ea84', 1, 'verb', null, 'to shut down (a business, system)', 'Virksomheden lukkede ned efter mange år med underskud.', 'The company closed down after many years of losses.'), ('lukke op', 'phrase', 'e6a7d336-8bcd-5012-aa2f-a4753c6cd6d0', 1, 'verb', null, 'to open (a door, window, etc.)', 'Hun lukker op for gæsterne, når de ringer på.', 'She opens the door for the guests when they ring the doorbell.'), ('lukke øjnene for', 'phrase', '2159d728-7068-5bb2-a555-f90192658880', 1, 'verb', null, 'to turn a blind eye to', 'Mange lukker øjnene for problemerne i samfundet.', 'Many people turn a blind eye to the problems in society.'), ('hen imod', 'phrase', 'a74051c8-82e6-5a6b-ba9b-95629703a9b2', 1, 'preposition', null, 'towards (time)', 'Det bliver koldt hen imod aften.', 'It will be cold towards evening.'), ('sætte sig hen', 'phrase', '43497df0-216a-5237-b560-85c4119ffd82', 1, 'verb', null, 'to sit down (moving to a spot)', 'Hun sætter sig hen ved vinduet hver morgen.', 'She sits down by the window every morning.'), ('sælge sig selv', 'phrase', '2cf4c858-0f21-52b7-b4c5-729d01f33495', 1, 'verb', null, 'to sell oneself (present oneself favourably)', 'Til jobsamtalen skal du sælge dig selv på en god måde.', 'At the job interview, you need to sell yourself in a good way.'), ('arbejde sort', 'phrase', 'd2c6214d-145d-57ef-b93b-0747792eff54', 1, 'verb', null, 'to work off the books', 'Mange håndværkere arbejder sort om sommeren.', 'Many craftsmen work off the books in the summer.'), ('gå i sort', 'phrase', 'cfe6b936-e1b0-5e81-aa58-d6203ca87271', 1, 'verb', null, 'to crash (of a computer, device)', 'Min computer gik i sort midt i mødet.', 'My computer crashed in the middle of the meeting.'), ('tage på tur', 'phrase', 'db5837c2-eadd-5604-ba23-f8491fab6f33', 1, 'verb', null, 'to go on a trip', 'Vi tager på tur til stranden i morgen.', 'We are going on a trip to the beach tomorrow.'), ('rødt kort', 'phrase', '6ec4a9d7-a356-580d-97e4-f32c3f780f10', 1, 'phrase', null, 'red card (in sports)', 'Dommeren viste ham et rødt kort.', 'The referee showed him a red card.'), ('se rødt', 'phrase', 'e38a6e2f-7dc3-5704-8ca6-f56c4cfd4e07', 1, 'verb', null, 'to see red', 'Jeg ser rødt, når nogen lyver for mig.', 'I see red when someone lies to me.'), ('være skyld i', 'phrase', '9160df79-f917-5f2e-840c-1eab561bd78e', 1, 'verb', null, 'to be the cause of (something bad)', 'Den kraftige regn var skyld i oversvømmelsen.', 'The heavy rain was the cause of the flooding.'), ('passe ind', 'phrase', 'a9aa180f-eafb-5cfb-86e2-025a898c4ca5', 1, 'verb', null, 'to fit in', 'Han passer ind i den nye klasse.', 'He fits into the new class.'), ('passe sig', 'phrase', '2e0a7e93-bad5-5abb-9b05-1b1f0c35e5d8', 1, 'verb', null, 'to be appropriate, to be fitting', 'Det passer sig ikke at tale højt i kirken.', 'It is not appropriate to speak loudly in church.'), ('hænge fast', 'phrase', 'c6d4806d-129c-5309-942a-704a6f5a7092', 1, 'verb', null, 'to get stuck (caught)', 'Min jakke hang fast i døren.', 'My jacket was stuck in the door.'), ('hænge fast', 'phrase', 'fc976d02-b60c-5f23-926f-128ee0c286cb', 2, 'verb', null, 'to freeze (computer)', 'Computeren hænger fast igen.', 'The computer is stuck again.'), ('hænge sig i', 'phrase', '49270748-ce11-5e07-b56f-e80b2fa01413', 1, 'verb', null, 'to get hung up (on details)', 'Du hænger dig i små fejl hele tiden.', 'You get hung up on small mistakes all the time.'), ('hænge ved', 'phrase', '8e08a5e1-b8ce-5fef-b227-9496972daebb', 1, 'verb', null, 'to cling (smell, dirt)', 'Røglugten hang ved mit tøj efter festen.', 'The smell of smoke clung to my clothes after the party.'), ('stemme om', 'phrase', '65960fb4-8b7b-5c95-b96c-fec7cc8c7d14', 1, 'verb', null, 'to vote (on something)', 'Vi stemmer om forslaget i morgen.', 'We will vote on the proposal tomorrow.'), ('blive rød i hovedet', 'phrase', '80e73576-9209-595b-b70a-fceb41c4548f', 1, 'verb', null, 'to blush', 'Hun bliver rød i hovedet, når hun får komplimenter.', 'She blushes when she receives compliments.'), ('hænge med hovedet', 'phrase', 'dbb41d9b-cf12-5d41-b398-cb6c71d92883', 1, 'verb', null, 'to be downcast, to mope', 'Han hang med hovedet hele dagen efter nyheden.', 'He moped around all day after the news.'), ('regne efter', 'phrase', 'bd3846eb-dee1-5bb5-a3da-2a7dd8301c2f', 1, 'verb', null, 'to recalculate, to check (a calculation)', 'Jeg regner efter for at være sikker.', 'I do the math to be sure.'), ('mærke på', 'phrase', '9c645e45-3173-5a88-a231-a2c01ffaf7e7', 1, 'verb', null, 'to feel (by touch, taste, etc.)', 'Jeg kan mærke på glasset at det er varmt.', 'I can feel from the glass that it is hot.'), ('komme til magten', 'phrase', '687b8263-c0ed-51c1-8b6a-a7cab5bb1f08', 1, 'verb', null, 'to come to power', 'Partiet kom til magten efter et tæt valg.', 'The party came to power after a close election.'), ('sige stop', 'phrase', 'c99b5f53-6d69-5245-b2db-17bc412f9223', 1, 'verb', null, 'to stop (doing something)', 'Han sagde stop efter tre års studier.', 'He quit after three years of study.'), ('handle derefter', 'phrase', 'ba935f54-5854-5a25-a4af-b4a16d1f1e99', 1, 'verb', null, 'act accordingly', 'Jeg forstår beskeden og handler derefter.', 'I understand the message and act accordingly.'), ('bære på', 'phrase', '7cbe18d6-78f6-5a8d-94ce-a085ee4c4df2', 1, 'verb', null, 'to carry (in one''s arms)', 'Hun bærer på en tung kasse.', 'She is carrying a heavy box.'), ('bære på', 'phrase', '48dce0c5-20b9-589b-8f67-c23c990f7c5c', 2, 'verb', null, 'to harbour (a feeling)', 'Han bærer på en stor sorg.', 'He carries a great sorrow.'), ('holde pause', 'phrase', '17d3e9cf-88c7-5654-8474-8e54c344f311', 1, 'verb', null, 'to take a break', 'Vi holder pause klokken tolv.', 'We take a break at twelve.'), ('slå fejl', 'phrase', '6fd2b113-53a3-5320-8e0d-2cf0f4d1680d', 1, 'verb', null, 'to fail, to go wrong', 'Planen slog fejl, og vi måtte starte forfra.', 'The plan failed, and we had to start over.'), ('få besøg', 'phrase', '3bee2ab8-ed74-5688-83eb-0f3d00c0c904', 1, 'verb', null, 'to have visitors', 'Vi får besøg af mine forældre i weekenden.', 'We will have a visit from my parents this weekend.'), ('være på besøg hos', 'phrase', '8ccd6f46-4458-5fab-a385-43deac6845f4', 1, 'verb', null, 'to be visiting (someone)', 'Jeg er på besøg hos min ven i dag.', 'I''m visiting my friend today.'), ('tjene på', 'phrase', '50da5ab9-9bf5-578e-aff8-ae6768f4957c', 1, 'verb', null, 'to earn money on (sth.)', 'De tjener på at sælge gamle møbler.', 'They earn money by selling old furniture.'), ('det er slut', 'phrase', '95d2a870-ff66-5dfb-b372-a00615bad506', 1, 'phrase', null, 'it''s over', 'Det er slut med gratis kaffe på kontoret.', 'No more free coffee in the office.'), ('give koncert', 'phrase', 'fe587f42-56bb-574c-ac4d-391eeedad903', 1, 'verb', null, 'to give a concert', 'Bandet giver koncert i parken på lørdag.', 'The band will give a concert in the park on Saturday.'), ('tage magten', 'phrase', 'e31e5516-00c3-5eec-8560-ce25f63d3151', 1, 'verb', null, 'to seize power', 'Oprørerne tog magten i landet efter krigen.', 'The rebels seized power in the country after the war.'), ('gå ud at spise', 'phrase', 'cb143ec2-fc72-5c9f-9868-1fc5ed53093e', 1, 'verb', null, 'to eat out', 'Vi gik ud at spise i fredags.', 'We went out to eat on Friday.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0013' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
